"""Explain public checks, nested report suppression and shared report buffers."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1825': ('접수처에서 검사할 물건의 위치와 크기를 알려 주듯, 이 함수는 검사할 메모리의 주소와 길이를 내부 담당 함수에 넘겨요.', '공개 검사 함수의 입구 조건과 전달하는 정보를 이해합니다.', '검사 꺼짐→돌아가기, 검사 켜짐→주소·길이·NULL·REASON_ANY 전달이라는 두 길을 그리세요.', ['KMSAN은 아직 준비되지 않은 메모리 값을 사용하는 실수를 찾는 도구예요. kmsan_check_memory는 지정한 메모리 범위를 검사해 달라고 요청하는 공개 함수예요. 공개 함수라는 말은 다른 코드가 정해진 사용법에 따라 호출할 수 있다는 뜻이에요.', 'addr는 검사할 첫 위치의 주소이고 size는 검사할 길이예요. 길이는 바이트라는 단위로 세어요. 예를 들어 size가 8이면 addr부터 시작하는 8바이트 범위를 검사하도록 요청해요.', '첫 조건은 !kmsan_enabled예요. !는 아니다라는 뜻이므로 검사가 켜져 있지 않으면 return으로 돌아가요. 켜져 있으면 내부 함수 kmsan_internal_check_memory를 호출해요.', '내부 함수에는 주소, 길이, NULL, REASON_ANY를 차례대로 넘겨요. 여기의 NULL은 별도로 덧붙일 사용자 공간 주소가 없다는 표시예요. 검사할 첫 번째 주소 addr까지 없다는 뜻은 아니에요. 사용자 공간은 일반 프로그램이 사용하는 메모리 영역을 말해요.', 'REASON_ANY는 이 요청에 붙이는 일반적인 검사 이유예요. USB 장치로 보내는 상황을 나타내는 REASON_SUBMIT_URB와 달라요. 검사 이유가 다르면 내부 보고 코드에서 문제를 설명하는 종류도 달라질 수 있어요.', '이 짧은 본문에는 내부 작업 시작·끝을 표시하는 enter_runtime과 leave_runtime이 없어요. 이미 내부 작업 중인지 확인하는 조건도 직접 넣지 않아요. 실제 검사와 보고에는 다른 함수의 조건이 더 있으므로 이 입구를 통과했다고 반드시 오류 문장이 출력되는 것은 아니에요.'], [('이 공개 검사 함수가 내부 함수에 넘기는 검사 이유는 무엇인가요?', ['언제나 USB 전송을 뜻하는 REASON_SUBMIT_URB예요', '일반적인 검사 이유인 REASON_ANY예요'], '정답은 두 번째예요. 호출문의 마지막 인자가 REASON_ANY예요. 다른 USB 관련 함수에서 보았던 이유를 이 함수에도 그대로 적용하면 안 돼요.'), ('이 공개 함수 본문에 enter_runtime과 leave_runtime 호출이 있나요?', ['아니요. 켜짐 여부를 확인하고 내부 검사 함수를 호출해요', '네. 모든 공개 함수에는 똑같이 두 호출이 있어요'], '정답은 첫 번째예요. 함수마다 맡은 일이 달라 조건과 호출도 달라요. 내부 검사와 보고의 조건은 해당 함수에서 확인해야 하며, 여기 없는 호출을 있다고 생각하면 안 돼요.')]), 'os1826': ('문에 잠시 기다려 주세요라는 쪽지를 두 장 붙였다면 한 장만 떼어서는 끝이 아니에요. 기다리라는 요청이 몇 개 남았는지 숫자로 세어요.', '보고를 잠시 막는 중첩 횟수와 되돌리는 순서를 이해합니다.', '0에서 시작해 중지·중지·복구·복구를 적용하고 0→1→2→1→0을 적으세요.', ['current는 지금 실행 중인 작업을 가리켜요. current->kmsan_ctx.depth는 그 작업에서 KMSAN 보고를 잠시 막는 요청이 몇 겹 남아 있는지 세는 숫자예요. ->는 가리키는 구조체 안의 항목을 고르는 C 문법이에요.', 'kmsan_disable_current는 depth를 1 늘려요. ++가 1 더하기라는 뜻이에요. kmsan_enable_current는 depth를 1 줄이고, --는 1 빼기라는 뜻이에요. 이름에 enable이 있어도 언제나 숫자를 0으로 만드는 것은 아니에요.', '처음 depth가 0이라고 해 봐요. 바깥 작업이 보고 중지를 요청하면 1, 그 안에서 부른 다른 작업도 중지를 요청하면 2가 돼요. 이렇게 작업 안에 또 작업이 들어가는 것을 중첩이라고 해요.', '안쪽 작업이 끝나 enable을 한 번 부르면 2에서 1이 돼요. 바깥 작업의 요청이 아직 남아 있으므로 보고가 계속 억제돼요. 바깥 작업도 끝나 한 번 더 부르면 0으로 돌아와요. report 함수는 depth가 0이 아니면 보고를 시작하지 않아요.', '따라서 일찍 돌아가거나 오류가 나는 길에서도 중지 요청과 복구 호출의 짝을 맞춰야 해요. 호출을 빠뜨리면 보고가 계속 막힐 수 있고 너무 많이 복구하면 숫자 범위를 벗어나는 문제가 생겨요.', '이 depth와 kmsan_in_runtime은 다른 항목이에요. depth는 현재 작업의 보고 억제 횟수이고, kmsan_in_runtime은 검사 도구 내부 작업 중인지 판단하는 데 쓰이는 상태예요. 과거 발생 경로 기록의 깊이 역시 또 다른 개념이에요. 이름에 깊이가 들어간다고 같은 숫자는 아니에요.'], [('depth가 0일 때 disable 두 번, enable 한 번을 부르면 얼마인가요?', ['enable을 불렀으므로 무조건 0이에요', '0→1→2→1이므로 1이에요'], '정답은 두 번째예요. enable은 한 겹만 되돌려요. 두 번 중지하고 한 번 복구했으니 중지 요청 하나가 남아 있어요.'), ('보고 억제 횟수 depth와 내부 작업 상태 kmsan_in_runtime은 같은 항목인가요?', ['아니요. 역할이 다른 별도의 상태예요', '네. 같은 숫자를 두 이름으로 불러요'], '정답은 첫 번째예요. 구조체에도 서로 다른 항목으로 선언되어 있어요. 보고를 잠시 막는 일과 내부 작업에 다시 들어가는 것을 조절하는 일은 구별해야 해요.')]), 'os1827': ('경고등이 켜진다고 숫자판이 저절로 고쳐지는 것은 아니에요. 경고하는 문장과 숫자를 바꾸는 문장의 순서를 따로 살펴봐요.', '경고와 숫자 보정을 구별하고 부호 없는 정수의 경계를 이해합니다.', '0부터 7까지 표시하는 장난감 숫자판에서 0의 한 칸 이전은 7, 7의 한 칸 다음은 0이라고 그리세요. 실제 depth는 더 큰 범위예요.', ['depth는 unsigned int, 즉 음수를 나타내지 않는 정수 형식이에요. 담을 수 있는 가장 큰 값은 정해져 있어요. 범위를 벗어나는 덧셈·뺄셈에서는 값이 반대쪽 끝으로 돌아가요. 이 현상을 되감김이라고 생각하면 돼요.', '0부터 7까지 세는 작은 숫자판을 가정하면 0에서 1을 빼면 7, 7에 1을 더하면 0으로 돌아가요. 실제 depth의 최댓값이 7이라는 뜻은 아니에요. 작은 모형으로 부호 없는 정수 계산의 규칙을 설명한 거예요.', 'enable 함수는 먼저 depth가 0인지 경고하고, 그다음 depth--를 실행하는 순서예요. 경고 뒤 실행이 계속되면 0에서 감소해 unsigned int의 최댓값으로 돌아가요. 숫자를 0에 고정하거나 잘못된 호출을 자동으로 취소하는 코드는 없어요.', '여기서 KMSAN_WARN_ON은 단순한 출력만 하는 것도 아니에요. 조건이 참이면 KMSAN을 끄고, panic_on_kmsan 설정이 켜져 있으면 BUG 처리를 해 정상적으로 계속하지 못할 수 있어요. 따라서 경고 뒤 감소라는 설명은 경고 이후 실행이 계속되는 경우에 해당해요.', 'disable 함수는 반대로 depth++로 먼저 증가한 뒤 0인지 경고해요. 최댓값에서 증가하면 이미 0으로 돌아간 다음 경고 조건을 확인해요. 경고는 잘못된 상태를 알리는 것이며 증가 전에 값을 제한하는 장치가 아니에요.', '정상 사용법은 0에서 복구를 더 부르거나 최댓값까지 중지를 쌓는 것이 아니에요. 필요한 구간에서 disable과 enable의 횟수를 맞추세요. 경계 숫자판은 잘못된 짝이 왜 문제인지 배우기 위한 모형이며 실제 커널에서 오류를 일으키는 실습이 아니에요.'], [('depth가 0인데 enable을 잘못 불렀고 경고 뒤 실행이 계속된다면 어떻게 되나요?', ['경고가 감소를 취소해서 항상 0으로 남아요', '뒤의 감소문이 실행되어 부호 없는 정수의 최댓값으로 돌아가요'], '정답은 두 번째예요. 경고 뒤에 depth--가 있어요. 다만 경고 매크로는 KMSAN을 끄고 설정에 따라 BUG 처리도 하므로 언제나 정상 실행이 계속된다고 말할 수는 없어요.'), ('disable은 언제 depth가 0인지 경고하나요?', ['1을 늘린 뒤에 확인해요', '1을 늘리기 전에 확인해요'], '정답은 첫 번째예요. 원문의 depth++가 앞에 있어요. 최댓값에서 0으로 돌아갔다면 그 결과를 보고 경고하며, 미리 증가를 막거나 최댓값에 고정하지 않아요.')]), 'os1828': ('두 사람이 칠판 한 칸에 동시에 글을 쓰면 글자가 섞여요. 공용 설명 칸도 한 보고가 쓰는 동안 다른 보고가 덮어쓰지 못하게 해야 해요.', '공유 문자열 공간과 잠금의 필요성, 순서 모형의 한계를 이해합니다.', 'A가 잠금 얻기→설명 쓰기→출력하기→잠금 풀기를 그리세요. B는 같은 잠금을 얻은 뒤 자기 설명을 쓰도록 놓으세요.', ['KMSAN 보고는 문제가 생긴 위치와 관련 설명을 출력해요. pretty_descr는 지역 변수 설명을 보기 좋게 가공하는 함수예요. 지역 변수는 함수 안에서 사용하는 값이고, 문자열은 글자를 차례로 담은 데이터예요.', '예를 들어 ----apple@pick이라는 설명에서 -는 건너뛰고 @를 만나면 멈춰 apple을 남겨요. 이 결과는 report_local_descr라는 전역 배열에 써요. 전역이라는 말은 여러 호출이 같은 저장 공간을 함께 사용한다는 뜻이에요.', '이 배열은 DESCR_SIZE가 정한 128칸이에요. C 문자열은 마지막에 끝을 뜻하는 0을 넣어야 하므로 최대 127개의 내용 문자를 담아요. 매번 제한 없이 새 공간을 얻는 방식이 아니에요. 원문 주석은 메모리 할당을 피하려고 전역 공간을 쓴다고 설명해요.', '공유 공간에는 위험도 있어요. A 보고가 apple을 써 놓고 출력하기 전에 B 보고가 pear로 덮어쓰면 A의 설명이 바뀔 수 있어요. 잠금은 같은 규칙을 따르는 보고들이 이 공간을 한 번에 하나씩 쓰게 하는 장치예요.', 'kmsan_report는 kmsan_report_lock이라는 raw spinlock을 얻은 뒤 출력과 발생 위치 설명 처리를 하고 잠금을 풀어요. spinlock은 다른 쪽이 사용하는 동안 잠금이 풀리는지 반복해서 확인하며 기다리는 잠금이에요. pretty_descr 자체가 잠금을 얻는 것이 아니라 보고하는 바깥 경로에서 보호해요.', '종이에 잠금→가공→출력→해제를 그리거나 한 번 실행한 호출 기록을 보면 순서는 확인할 수 있어요. 하지만 여러 CPU가 실제로 동시에 실행되는 모든 경우를 시험한 것은 아니에요. CPU는 코드를 실행하는 장치이고, 실제 경쟁과 인터럽트 조건의 검증에는 별도의 검사가 필요해요.'], [('pretty_descr가 가공한 설명을 담는 곳은 어디인가요?', ['호출할 때마다 제한 없이 새로 얻는 메모리예요', '보고 잠금으로 보호하는 공용 전역 배열이에요'], '정답은 두 번째예요. report_local_descr라는 128칸 배열을 재사용해요. 새 공간 할당을 피하는 대신 동시에 서로의 글을 덮어쓰지 않도록 보고 경로에서 잠금으로 보호해요.'), ('한 번 실행한 모형에서 잠금과 해제 순서가 맞으면 모든 CPU 경쟁도 검증된 건가요?', ['아니요. 그 모형에서는 호출 순서를 확인한 것이에요', '네. 모든 동시 실행 상황까지 시험한 것이에요'], '정답은 첫 번째예요. 한 사람이 차례로 칠판을 쓰는 연습과 여러 사람이 동시에 쓰려는 상황은 달라요. 순서 기록만으로 실제 모든 동시 실행이 올바르다고 증명할 수는 없어요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_452.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
